{"file_path":"/app/check_cert.py","content":"#!/usr/bin/env python3
"""
check_cert.py - Verify the self-signed development certificate.

Checks performed:
  * The certificate and private key files exist.
  * The certificate file contains valid, loadable PEM data.
  * The private key matches the certificate.
  * The certificate's Common Name and Organization match expectations.
  * The certificate is currently within its validity period.

On success, prints the certificate details and the message:
    Certificate verification successful
"""

import hashlib
import os
import ssl
import subprocess
from datetime import datetime, timezone

CERT_FILE = "/app/ssl/server.crt"
KEY_FILE = "/app/ssl/server.key"
EXPECTED_CN = "dev-internal.company.local"
EXPECTED_ORG = "DevOps Team"

OPENSSL_DATE_FORMAT = "%b %d %H:%M:%S %Y %Z"
ISO_DATE_FORMAT = "%Y-%m-%d"


def fail(message):
    """Print an error and exit with a non-zero status."""
    raise SystemExit(f"ERROR: {message}")


def sha256_fingerprint(pem):
    """Return the SHA-256 fingerprint of the certificate, colon-separated."""
    der = ssl.PEM_cert_to_DER_cert(pem)
    digest = hashlib.sha256(der).hexdigest().upper()
    return ":".join(digest[i:i + 2] for i in range(0, len(digest), 2))


def subject_fields(info):
    """Extract subject name/value pairs from parsed certificate info."""
    fields = {}
    subject = info.get("subject", ())
    if isinstance(subject, dict):  # fallback parser may return a dict
        return {str(k).lower(): v for k, v in subject.items()}
    for rdn in subject:
        for item in rdn:
            if isinstance(item, (tuple, list)) and len(item) == 2:
                key, value = item
                fields[key] = value
    return fields


def to_iso_date(value):
    """Convert an OpenSSL date string to YYYY-MM-DD or return None."""
    if not value:
        return None
    try:
        return datetime.strptime(value, OPENSSL_DATE_FORMAT).strftime(ISO_DATE_FORMAT)
    except ValueError:
        try:
            # Retry without the trailing timezone token (e.g. "GMT").
            cleaned = value.rsplit(" ", 1)[0]
            return datetime.strptime(cleaned, "%b %d %H:%M:%S %Y").strftime(ISO_DATE_FORMAT)
        except ValueError:
            return None


def parse_with_openssl(cert_path):
    """Fallback: parse certificate details using the openssl CLI."""
    out = subprocess.check_output(
        [
            "openssl", "x509", "-in", cert_path, "-noout",
            "-subject", "-issuer", "-dates", "-fingerprint", "-sha256",
        ],
        text=True,
    )
    info = {}
    for line in out.splitlines():
        if line.startswith("subject="):
            subject = {}
            for part in line[len("subject="):].split(","):
                key, _, value = part.strip().partition("=")
                subject[key.strip()] = value.strip()
            info["subject"] = subject
        elif line.startswith("issuer="):
            issuer = {}
            for part in line[len("issuer="):].split(","):
                key, _, value = part.strip().partition("=")
                issuer[key.strip()] = value.strip()
            info["issuer"] = issuer
        elif line.startswith("notBefore="):
            info["notBefore"] = line[len("notBefore="):]
        elif line.startswith("notAfter="):
            info["notAfter"] = line[len("notAfter="):]
    return info


def load_certificate_info(cert_path):
    """Return certificate metadata, preferring ssl internal parser."""
    try:
        from ssl import _ssl as ssl_private
        return ssl_private._test_decode_cert(cert_path)
    except (ImportError, AttributeError, TypeError, ValueError, OSError):
        return parse_with_openssl(cert_path)


def main():
    # 1. Required files must exist.
    for path in (CERT_FILE, KEY_FILE):
        if not os.path.isfile(path):
            fail(f"Required file not found: {path}")

    # 2. Certificate must be loadable as PEM data.
    try:
        with open(CERT_FILE, "r", encoding="utf-8") as handle:
            pem = handle.read()
        ssl.PEM_cert_to_DER_cert(pem)
    except (OSError, ValueError) as exc:
        fail(f"Certificate could not be loaded: {exc}")

    # 3. Private key must match the certificate.
    try:
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=CERT_FILE, keyfile=KEY_FILE)
    except (ssl.SSLError, OSError) as exc:
        fail(f"Private key does not match the certificate: {exc}")

    # 4. Extract and display certificate details.
    info = load_certificate_info(CERT_FILE)
    fields = subject_fields(info)

    cn = fields.get("commonName", "")
    org = fields.get("organizationName", "")
    valid_from = to_iso_date(info.get("notBefore", ""))
    expires = to_iso_date(info.get("notAfter", ""))
    fingerprint = sha256_fingerprint(pem)

    print(f"Certificate file: {CERT_FILE}")
    print(f"Subject: O={org}, CN={cn}")
    print(f"Valid from: {valid_from}")
    print(f"Expiration date (YYYY-MM-DD): {expires}")
    print(f"SHA-256 fingerprint: {fingerprint}")

    # 5. Validate expected values.
    checks_pass = True

    if cn != EXPECTED_CN:
        print(f"FAIL: Expected Common Name '{EXPECTED_CN}', got '{cn}'")
        checks_pass = False

    if org != EXPECTED_ORG:
        print(f"FAIL: Expected Organization '{EXPECTED_ORG}', got '{org}'")
        checks_pass = False

    if not expires:
        print("FAIL: Could not determine certificate expiration date")
        checks_pass = False
    else:
        try:
            expiration = datetime.strptime(expires, ISO_DATE_FORMAT).date()
            today = datetime.now(timezone.utc).date()
            if expiration < today:
                print(f"FAIL: Certificate already expired ({expires})")
                checks_pass = False
            if valid_from and datetime.strptime(valid_from, ISO_DATE_FORMAT).date() > today:
                print(f"FAIL: Certificate is not yet valid ({valid_from})")
                checks_pass = False
        except ValueError:
            print("FAIL: Invalid date format in certificate")
            checks_pass = False

    if checks_pass:
        print("Certificate verification successful")
    else:
        fail("Certificate verification failed")


if __name__ == "__main__":
    main()
"}
